// Package connection manages the connections that authorize CircleCI to act
// for an organization at a VCS provider, through the V3 API.
package connection

import (
	"context"
	"net/http"
	"net/url"

	"terraform-provider-circleci/internal/circleci/client"
)

const (
	ProviderForgejo = "forgejo"

	PurposeConnection = "connection"
	PurposeCheckout   = "checkout"
)

// ForgejoSetup is what CircleCI needs to connect an organization to a Forgejo
// instance. Both audiences are generated by Forgejo for Authorized
// Integrations that must already exist when setup is called.
type ForgejoSetup struct {
	URL                string
	Owner              string
	ConnectionAudience string
	CheckoutAudience   string
	RequestHeaders     map[string]string
}

type Owner struct {
	ID    string `json:"id"`
	Login string `json:"login"`
	Type  string `json:"type"`
}

// Webhook is the webhook to create at the provider so it delivers events to
// CircleCI.
type Webhook struct {
	URL    string   `json:"url"`
	Secret string   `json:"secret"`
	Events []string `json:"events"`
}

type SetupResult struct {
	ID      string
	Owner   Owner
	Webhook Webhook
}

type Access struct {
	Type     string `json:"type"`
	Audience string `json:"audience"`
	Subject  string `json:"subject"`
	Issuer   string `json:"issuer"`
}

type WebhookSecretState struct {
	CurrentAddedAt    string `json:"current_added_at"`
	IsRotationPending bool   `json:"is_rotation_pending"`
}

// Credentials describes how CircleCI authenticates to the provider. It never
// carries a secret value.
type Credentials struct {
	Access             map[string]Access  `json:"access"`
	WebhookSecret      WebhookSecretState `json:"webhook_secret"`
	RequestHeaderNames []string           `json:"request_header_names"`
}

type Connection struct {
	ID                 string
	Provider           string       `json:"provider"`
	ProviderURL        string       `json:"provider_url"`
	ExternalID         string       `json:"external_id"`
	TargetType         string       `json:"target_type"`
	Login              string       `json:"login"`
	ConnectionError    string       `json:"connection_error"`
	AuthorizationError string       `json:"authorization_error"`
	Credentials        *Credentials `json:"credentials"`
}

type Service struct {
	client *client.Client
}

func NewService(c *client.Client) *Service {
	return &Service{client: c}
}

type setupVCS struct {
	Provider           string            `json:"provider"`
	URL                string            `json:"url"`
	Owner              string            `json:"owner"`
	ConnectionAudience string            `json:"connection_audience"`
	CheckoutAudience   string            `json:"checkout_audience"`
	RequestHeaders     map[string]string `json:"request_headers,omitempty"`
}

type setupRequest struct {
	Type string   `json:"type"`
	VCS  setupVCS `json:"vcs"`
}

type setupAttributes struct {
	NextStep string   `json:"next_step"`
	Owner    *Owner   `json:"owner"`
	Webhook  *Webhook `json:"webhook"`
}

// SetupForgejo connects orgID to a Forgejo instance. CircleCI checks the
// instance and both Authorized Integrations before storing anything, and an
// organization can have only one Forgejo connection.
func (s *Service) SetupForgejo(ctx context.Context, orgID string, setup ForgejoSetup) (*SetupResult, error) {
	req := setupRequest{
		Type: "vcs",
		VCS: setupVCS{
			Provider:           ProviderForgejo,
			URL:                setup.URL,
			Owner:              setup.Owner,
			ConnectionAudience: setup.ConnectionAudience,
			CheckoutAudience:   setup.CheckoutAudience,
			RequestHeaders:     setup.RequestHeaders,
		},
	}
	var resp client.V3Data[client.V3Entity[setupAttributes, struct{}]]
	_, err := s.client.V3(ctx, http.MethodPost, "/provider/connections/setup", url.Values{"filter[org_id]": {orgID}}, req, &resp)
	if err != nil {
		return nil, err
	}

	result := &SetupResult{ID: resp.Data.ID}
	if resp.Data.Attributes.Owner != nil {
		result.Owner = *resp.Data.Attributes.Owner
	}
	if resp.Data.Attributes.Webhook != nil {
		result.Webhook = *resp.Data.Attributes.Webhook
	}
	return result, nil
}

func (s *Service) Get(ctx context.Context, id string) (*Connection, error) {
	var resp client.V3Data[client.V3Entity[Connection, struct{}]]
	_, err := s.client.V3(ctx, http.MethodGet, "/provider/connections/"+url.PathEscape(id), nil, nil, &resp)
	if err != nil {
		return nil, err
	}
	conn := resp.Data.Attributes
	conn.ID = resp.Data.ID
	return &conn, nil
}

// List returns the organization's provider connections, of every provider.
func (s *Service) List(ctx context.Context, orgID string) ([]Connection, error) {
	items, err := client.V3ListAll[client.V3Entity[Connection, struct{}]](ctx, s.client, "/provider/connections", url.Values{"filter[org_id]": {orgID}})
	if err != nil {
		return nil, err
	}
	conns := make([]Connection, 0, len(items))
	for _, item := range items {
		conn := item.Attributes
		conn.ID = item.ID
		conns = append(conns, conn)
	}
	return conns, nil
}

// Delete removes the connection and everything CircleCI holds beneath it,
// including the pipelines and triggers built on its repositories. It changes
// nothing at the provider.
func (s *Service) Delete(ctx context.Context, id string) error {
	_, err := s.client.V3(ctx, http.MethodDelete, "/provider/connections/"+url.PathEscape(id), nil, nil, nil)
	return err
}

// SetOIDCAudience replaces the audience CircleCI uses for one purpose,
// PurposeConnection or PurposeCheckout.
func (s *Service) SetOIDCAudience(ctx context.Context, id, purpose, audience string) error {
	req := map[string]string{"purpose": purpose, "audience": audience}
	_, err := s.client.V3(ctx, http.MethodPost, "/provider/connections/"+url.PathEscape(id)+"/set-oidc-audience", nil, req, nil)
	return err
}

// SetRequestHeaders replaces the whole set of headers sent to the provider and
// returns their names as CircleCI stored them. An empty set clears them.
func (s *Service) SetRequestHeaders(ctx context.Context, id string, headers map[string]string) ([]string, error) {
	if headers == nil {
		headers = map[string]string{}
	}
	req := map[string]map[string]string{"request_headers": headers}
	var resp client.V3Data[client.V3Entity[struct {
		RequestHeaderNames []string `json:"request_header_names"`
	}, struct{}]]
	_, err := s.client.V3(ctx, http.MethodPost, "/provider/connections/"+url.PathEscape(id)+"/set-request-headers", nil, req, &resp)
	if err != nil {
		return nil, err
	}
	return resp.Data.Attributes.RequestHeaderNames, nil
}

// RotateWebhookSecret issues a new webhook secret and returns it. The current
// secret keeps verifying deliveries until one signed with the new secret
// arrives.
func (s *Service) RotateWebhookSecret(ctx context.Context, id string) (string, error) {
	var resp client.V3Data[client.V3Entity[struct {
		Webhook struct {
			Secret string `json:"secret"`
		} `json:"webhook"`
	}, struct{}]]
	_, err := s.client.V3(ctx, http.MethodPost, "/provider/connections/"+url.PathEscape(id)+"/rotate-webhook-secret", nil, nil, &resp)
	if err != nil {
		return "", err
	}
	return resp.Data.Attributes.Webhook.Secret, nil
}
